SUBJECTS.push({id:"anglais",name:"Anglais",short:"Compréhension, vocabulaire et expression",emoji:"🇬🇧",color:"#e4efff",ink:"#3157a8",topics:[
{title:"Se présenter et parler de ses expériences",tag:"Expression orale",body:"Pour parler de soi, utilise des phrases simples et des temps adaptés à ce que tu racontes.",bullets:["Présent simple : I live in France; I enjoy reading.","Be + adjectif : I am interested in science; I am proud of my project.","Prétérit pour une expérience terminée : I visited London last year.","Organise ta présentation : identity, interests, school, plans and examples.","Prépare des connecteurs : first, then, because, however, finally."],tip:"Développe tes réponses avec une raison ou un exemple plutôt que de répondre par un seul mot."},
{title:"Présent simple et présent en be + -ing",tag:"Grammaire",body:"Le présent simple décrit notamment les habitudes et les faits ; be + -ing décrit souvent une action en cours ou une situation temporaire.",bullets:["I play football every Saturday : habitude.","I am studying now : action en cours.","À la troisième personne du singulier, ajoute généralement -s au présent simple.","Question au présent simple : Do you like music? / Does she like music?", "Négation : don't/doesn't + base verbale ; be + -ing utilise am/is/are + verbe en -ing."],tip:"Repère les marqueurs de temps comme usually, every day, now et at the moment."},
{title:"Prétérit et récit au passé",tag:"Grammaire",body:"Le prétérit permet de raconter des actions terminées dans le passé, notamment dans un récit.",bullets:["Verbes réguliers : base verbale + -ed (visited, played).","Certains verbes sont irréguliers : go/went, see/saw, have/had, make/made.","Question : Did you see it? Négation : I didn't see it.","Après did/didn't, utilise la base verbale : did go, pas did went.","Utilise des marqueurs : yesterday, last week, two years ago."],tip:"Apprends les verbes irréguliers les plus fréquents et réutilise-les dans de courtes phrases."},
{title:"Exprimer son opinion et argumenter",tag:"Expression écrite",body:"Pour défendre une opinion en anglais, donne ton avis, une raison et un exemple.",bullets:["Opinion : I think…, In my opinion…, I believe…","Ajouter : moreover, also, furthermore.","Opposer : however, on the other hand, although.","Justifier : because, since, for example.","Conclure : to sum up, therefore, in conclusion."],tip:"Varie les connecteurs et vérifie que chaque argument est accompagné d’une explication."},
{title:"Comprendre un document en anglais",tag:"Compréhension",body:"Pour comprendre un texte ou un document audio, repère le contexte général avant les détails.",bullets:["Lis le titre, identifie le type de document, l’auteur et la situation.","Repère les mots transparents sans supposer qu’ils ont toujours le même sens.","Cherche les mots-clés liés aux questions et aux informations de temps, lieu et personne.","Utilise le contexte pour déduire le sens d’un mot inconnu.","Reformule les informations essentielles avec des phrases simples."],tip:"Ne traduis pas chaque mot : cherche d’abord le sens global puis les indices utiles."}
],quiz:[
{q:"Choose the correct sentence for a habit.",a:["I am go to school every day.","I go to school every day.","I going school every day.","I goes to school every day."],correct:1,why:"Au présent simple, on dit « I go » ; le marqueur every day indique une habitude."},
{q:"What is the past form of 'go' ?",a:["goed","gone yesterday","went","going"],correct:2,why:"Le prétérit du verbe irrégulier go est went."},
{q:"Complete: 'She ___ watching TV now.'",a:["are","is","do","be"],correct:1,why:"Avec she, on utilise is + verbe en -ing au présent continu."},
{q:"Which phrase introduces an opinion?",a:["In my opinion, ...","Yesterday at ...","There are ... only","How many years?"],correct:0,why:"« In my opinion » sert à introduire un point de vue."},
{q:"Choose the correct question in the past.",a:["Did you saw it?","Did you see it?","Do you saw it?","Were you see it?"],correct:1,why:"Après did, le verbe reste à la base verbale : see."}
],cards:[["Habit in English","Present simple: I usually walk to school."],["Action happening now","Be + verb-ing: She is reading now."],["Past of go","Went."],["Give an opinion","In my opinion… / I think… / I believe…"],["Useful contrast connector","However = cependant." ] ]});

for (const s of SUBJECTS) {
 const extra = more[s.id];
 if (!extra) continue;
 s.topics.push(...extra.topics);
 s.quiz.push(...extra.quiz.map(item => Array.isArray(item) ? ({q:item[0],a:item[1],correct:item[2],why:item[3]}) : item));
 for (const t of extra.topics) {
   s.cards.push([`À retenir : ${t.title}`, `${t.body} ${t.bullets.slice(0,2).join(" ")}`]);
 }
}

const STORAGE_KEY = "capbrevet-progress-v1";
let state = loadState();
let currentSubject = SUBJECTS[0];
let currentMode = "notes";
let quizIndex = 0, quizScore = 0, quizAnswered = false, flashIndex = 0, flashRevealed = false, quizOrder = [], quizReviewMode = false;
let installPrompt = null;

function emptyState(){return {quizzes:{},cards:{},topics:{},oral:{},missed:{},planner:{settings:null,done:{}}}}
function loadState(){try{const saved=JSON.parse(localStorage.getItem(STORAGE_KEY))||{};return {...emptyState(),...saved,missed:saved.missed||{},planner:{settings:null,done:{},...(saved.planner||{})}}}catch(e){return emptyState()}}
function saveState(){localStorage.setItem(STORAGE_KEY,JSON.stringify(state));renderStats()}
function subjectById(id){return SUBJECTS.find(s=>s.id===id)||SUBJECTS[0]}
function totalTopics(){return SUBJECTS.reduce((n,s)=>n+s.topics.length,0)}
function totalQuizQuestions(){return SUBJECTS.reduce((n,s)=>n+s.quiz.length,0)}
function getSubjectProgress(s){let t=s.topics.filter((_,i)=>state.topics[s.id+"-"+i]).length;let q=state.quizzes[s.id]||0;let c=state.cards[s.id]||0;let max=s.topics.length+s.quiz.length+s.cards.length;return max?Math.round((t+Math.min(q,s.quiz.length)+Math.min(c,s.cards.length))/max*100):0}
function overallProgress(){let done=0,total=0;SUBJECTS.forEach(s=>{done+=s.topics.filter((_,i)=>state.topics[s.id+"-"+i]).length+(state.quizzes[s.id]||0)+(state.cards[s.id]||0);total+=s.topics.length+s.quiz.length+s.cards.length});return total?Math.round(done/total*100):0}
function renderStats(){const p=overallProgress();document.querySelector("#statProgress").textContent=p+"%";document.querySelector("#progressBar").style.width=p+"%";document.querySelector("#statQuizzes").textContent=Object.values(state.quizzes).reduce((a,b)=>a+b,0);document.querySelector("#statCards").textContent=Object.values(state.cards).reduce((a,b)=>a+b,0);document.querySelector("#progressBig").textContent=p+"%";document.querySelector("#ringValue").textContent=p+"%";document.querySelector("#progressRing").style.background=`conic-gradient(var(--blue) ${p*3.6}deg,#edf0fa 0deg)`;document.querySelector("#progressCaption").textContent=p===0?"Commence une première activité pour suivre tes progrès.":p<100?"Continue à ton rythme : chaque activité te rapproche de ton objectif.":"Bravo, tu as parcouru toutes les activités disponibles !";renderProgressSubjects()}
function renderSubjectTiles(targetId){const el=document.getElementById(targetId);el.innerHTML=SUBJECTS.map(s=>`<button class="${targetId==="homeSubjects"?"subject-tile":"subject-row"}" data-subject="${s.id}"><span class="subject-emoji" style="background:${s.color};color:${s.ink}">${s.emoji}</span><span class="${targetId==="allSubjects"?"subject-row-copy":""}"><b>${s.name}</b><small>${s.short}</small></span><span class="arrow">→</span></button>`).join("");el.querySelectorAll("[data-subject]").forEach(b=>b.addEventListener("click",()=>openSubject(b.dataset.subject)))}
function renderProgressSubjects(){const el=document.getElementById("progressSubjects");if(!el)return;el.innerHTML=SUBJECTS.map(s=>{const p=getSubjectProgress(s);return `<div class="progress-line"><div class="progress-line-top"><span class="subject-emoji" style="background:${s.color};color:${s.ink}">${s.emoji}</span><b>${s.name}</b><strong>${p}%</strong></div><div class="progress-track"><div class="progress-fill" style="width:${p}%;background:${s.ink}"></div></div></div>`}).join("");renderMistakeSummary()}
function renderMistakeSummary(){const summary=document.querySelector("#mistakeSummary"),actions=document.querySelector("#mistakeActions");if(!summary||!actions)return;const total=SUBJECTS.reduce((n,s)=>n+((state.missed&&state.missed[s.id])||[]).length,0);summary.innerHTML=`<strong>${total}</strong><span>${total===1?"question à revoir":"questions à revoir"}</span>`;actions.innerHTML=SUBJECTS.filter(s=>((state.missed&&state.missed[s.id])||[]).length).map(s=>`<button class="secondary-btn" data-review-subject="${s.id}">${s.emoji} ${s.name} · ${(state.missed[s.id]||[]).length} →</button>`).join("")||'<p class="muted small">Aucune erreur enregistrée pour le moment. Fais un QCM pour commencer.</p>';actions.querySelectorAll("[data-review-subject]").forEach(b=>b.addEventListener("click",()=>{openSubject(b.dataset.reviewSubject);openStudy("mistakes")}))}
function go(page){document.querySelectorAll(".page").forEach(p=>p.classList.toggle("active",p.id===page));document.querySelectorAll(".nav-item").forEach(b=>b.classList.toggle("active",b.dataset.go===page || (page==="subjectDetail"&&b.dataset.go==="subjects") || (page==="study"&&b.dataset.go==="subjects")));window.scrollTo({top:0,behavior:"smooth"});if(page==="progress"){renderStats();renderPlanner()}}
function openSubject(id){currentSubject=subjectById(id);document.querySelector("#subjectHeader").innerHTML=`<span class="subject-emoji" style="background:${currentSubject.color};color:${currentSubject.ink}">${currentSubject.emoji}</span><div><h1>${currentSubject.name}</h1><p>${currentSubject.short}</p></div>`;document.querySelector("#subjectStats").innerHTML=`<div><strong>${getSubjectProgress(currentSubject)}%</strong><p>Progression dans cette matière</p><div class="progress-track" style="margin-top:10px"><div class="progress-fill" style="width:${getSubjectProgress(currentSubject)}%;background:${currentSubject.ink}"></div></div></div><span class="subject-emoji" style="background:${currentSubject.color};color:${currentSubject.ink}">${currentSubject.emoji}</span>`;go("subjectDetail")}
function openStudy(mode){quizReviewMode=mode==="mistakes";currentMode=quizReviewMode?"quiz":mode;quizIndex=0;quizScore=0;quizAnswered=false;flashIndex=0;flashRevealed=false;quizOrder=quizReviewMode?((state.missed&&state.missed[currentSubject.id])||[]).slice():currentSubject.quiz.map((_,i)=>i);if(mode==="quiz")quizOrder.sort(()=>Math.random()-.5);document.querySelector("#studyBack").onclick=()=>go("subjectDetail");renderStudy();go("study")}
function renderStudy(){const names={notes:"Fiches de révision",quiz:quizReviewMode?"Révision des erreurs":"QCM d’entraînement",cards:"Flashcards"};document.querySelector("#studyHeading").innerHTML=`<p class="eyebrow">${currentSubject.name.toUpperCase()}</p><h1 class="study-title">${names[currentMode]}</h1><p class="study-subtitle">${currentMode==="notes"?"Comprends les notions essentielles.":currentMode==="quiz"?(quizReviewMode?"Concentre-toi sur les questions déjà ratées.":"Réponds aux questions et lis les corrections."):"Retourne les cartes pour vérifier ce que tu as mémorisé."}</p>`;const el=document.querySelector("#studyContent");if(currentMode==="notes")renderNotes(el);if(currentMode==="quiz")renderQuiz(el);if(currentMode==="cards")renderFlashcard(el)}
function renderNotes(el){el.innerHTML=currentSubject.topics.map((t,i)=>`<article class="content-card"><span class="pill">${t.tag}</span><h2>${t.title}</h2><p>${t.body}</p><ul>${t.bullets.map(x=>`<li>${x}</li>`).join("")}</ul><div class="callout"><b>À retenir :</b> ${t.tip}</div><button class="secondary-btn mark-topic" data-topic="${i}" style="margin-top:15px">${state.topics[currentSubject.id+"-"+i]?"✓ Fiche revue":"Marquer comme revue"}</button></article>`).join("");el.querySelectorAll(".mark-topic").forEach(b=>b.addEventListener("click",()=>{const k=currentSubject.id+"-"+b.dataset.topic;state.topics[k]=!state.topics[k];saveState();b.textContent=state.topics[k]?"✓ Fiche revue":"Marquer comme revue";document.querySelector("#subjectStats").innerHTML=`<div><strong>${getSubjectProgress(currentSubject)}%</strong><p>Progression dans cette matière</p><div class="progress-track" style="margin-top:10px"><div class="progress-fill" style="width:${getSubjectProgress(currentSubject)}%;background:${currentSubject.ink}"></div></div></div>`;toast(state.topics[k]?"Fiche ajoutée à ta progression":"Fiche retirée de ta progression")}))}
function renderQuiz(el){if(quizIndex>=quizOrder.length){const reviewCount=((state.missed&&state.missed[currentSubject.id])||[]).length;el.innerHTML=`<article class="content-card" style="text-align:center;padding:30px 22px"><div style="font-size:48px">${quizScore>=quizOrder.length*.7?"🎉":"💪"}</div><h2>${quizReviewMode?"Révision terminée !":"Quiz terminé !"}</h2><p>Tu as obtenu <b>${quizScore} / ${quizOrder.length}</b>.</p><p>${quizScore===quizOrder.length?"Excellent, sans faute !":quizScore>=quizOrder.length*.7?"Bien joué ! Continue à consolider tes acquis.":"Relis les fiches puis réessaie les questions difficiles."}</p>${reviewCount?'<button class="secondary-btn" id="reviewAgain">Revoir les erreurs restantes ('+reviewCount+') →</button> ':''}<button class="primary-btn" id="retryQuiz">${quizReviewMode?"Refaire le QCM complet":"Recommencer le QCM"} →</button></article>`;if(!quizReviewMode)state.quizzes[currentSubject.id]=(state.quizzes[currentSubject.id]||0)+1;saveState();const again=el.querySelector("#retryQuiz");if(again)again.onclick=()=>openStudy("quiz");const review=el.querySelector("#reviewAgain");if(review)review.onclick=()=>openStudy("mistakes");return}
const q=currentSubject.quiz[quizOrder[quizIndex]];el.innerHTML=`<article class="content-card"><div class="quiz-progress"><span>Question ${quizIndex+1} sur ${quizOrder.length}</span><span>Score : ${quizScore}</span></div><div class="progress-track"><div class="progress-fill" style="width:${(quizIndex/quizOrder.length)*100}%"></div></div><h2 class="quiz-question">${q.q}</h2><div class="answer-list">${q.a.map((a,i)=>`<button class="answer-btn" data-answer="${i}">${String.fromCharCode(65+i)}. ${a}</button>`).join("")}</div><div id="feedback"></div><div class="quiz-actions"><button id="nextQuestion" class="primary-btn hidden">${quizIndex===quizOrder.length-1?"Voir le résultat":"Question suivante"} →</button></div></article>`;
el.querySelectorAll("[data-answer]").forEach(b=>b.addEventListener("click",()=>{if(quizAnswered)return;quizAnswered=true;const choice=Number(b.dataset.answer),questionIndex=quizOrder[quizIndex];state.missed=state.missed||{};state.missed[currentSubject.id]=state.missed[currentSubject.id]||[];if(choice===q.correct){quizScore++;state.missed[currentSubject.id]=state.missed[currentSubject.id].filter(i=>i!==questionIndex)}else if(!state.missed[currentSubject.id].includes(questionIndex)){state.missed[currentSubject.id].push(questionIndex)}saveState();el.querySelectorAll("[data-answer]").forEach((btn,i)=>{btn.disabled=true;if(i===q.correct)btn.classList.add("correct");if(i===choice&&i!==q.correct)btn.classList.add("wrong")});const f=el.querySelector("#feedback");f.className="feedback "+(choice===q.correct?"good":"bad");f.innerHTML=`<b>${choice===q.correct?"Bonne réponse !":"Pas tout à fait."}</b> ${q.why}`;el.querySelector("#nextQuestion").classList.remove("hidden")}));
el.querySelector("#nextQuestion").onclick=()=>{if(!quizAnswered)return;quizIndex++;quizAnswered=false;renderQuiz(el)}}
function renderFlashcard(el){const cards=currentSubject.cards;if(flashIndex>=cards.length){el.innerHTML=`<article class="content-card" style="text-align:center;padding:30px"><div style="font-size:45px">✨</div><h2>Séance terminée !</h2><p>Tu as parcouru toutes les flashcards de ${currentSubject.name}.</p><button class="primary-btn" id="againCards">Revoir les cartes →</button></article>`;state.cards[currentSubject.id]=(state.cards[currentSubject.id]||0)+cards.length;saveState();el.querySelector("#againCards").onclick=()=>openStudy("cards");return}
const c=cards[flashIndex];el.innerHTML=`<div class="flash-counter">Carte ${flashIndex+1} sur ${cards.length}</div><div class="flash-wrap"><button id="flashcard" class="flashcard"><span class="flash-label">${flashRevealed?"RÉPONSE":"QUESTION"}</span><strong>${flashRevealed?c[1]:c[0]}</strong><span class="tap-hint">${flashRevealed?"Appuie pour revoir la question":"Appuie sur la carte pour retourner"}</span></button></div><div class="flash-actions"><button class="secondary-btn" id="prevCard" ${flashIndex===0?"disabled":""}>← Précédente</button><button class="primary-btn" id="nextCard">${flashIndex===cards.length-1?"Terminer":"Suivante →"}</button></div>`;
el.querySelector("#flashcard").onclick=()=>{flashRevealed=!flashRevealed;renderFlashcard(el)};el.querySelector("#prevCard").onclick=()=>{if(flashIndex>0){flashIndex--;flashRevealed=false;renderFlashcard(el)}};el.querySelector("#nextCard").onclick=()=>{flashIndex++;flashRevealed=false;renderFlashcard(el)}}
function toast(msg){const t=document.querySelector("#toast");t.textContent=msg;t.classList.add("show");clearTimeout(window._toastTimer);window._toastTimer=setTimeout(()=>t.classList.remove("show"),2200)}
document.querySelectorAll("[data-go]").forEach(b=>b.addEventListener("click",()=>go(b.dataset.go)));
document.querySelectorAll("[data-mode]").forEach(b=>b.addEventListener("click",()=>openStudy(b.dataset.mode)));
renderSubjectTiles("homeSubjects");renderSubjectTiles("allSubjects");renderStats();
// Recherche dans les matières, fiches, questions de QCM et flashcards.
function setupSubjectSearch(){const input=document.querySelector("#subjectSearch"),clear=document.querySelector("#clearSearch"),summary=document.querySelector("#searchSummary"),list=document.querySelector("#allSubjects");if(!input||!list)return;const filter=()=>{const q=input.value.trim().toLocaleLowerCase("fr");let visible=0;list.querySelectorAll("[data-subject]").forEach(btn=>{const s=subjectById(btn.dataset.subject);const hay=[s.name,s.short,...s.topics.flatMap(t=>[t.title,t.tag,t.body,...t.bullets,t.tip]),...s.quiz.map(x=>x.q),...s.cards.flat()].join(" ").toLocaleLowerCase("fr");const match=!q||hay.includes(q);btn.hidden=!match;if(match)visible++});summary.textContent=q?(visible+" matière(s) trouvée(s) pour « "+input.value.trim()+" »."):"Astuce : cherche un thème comme Pythagore, génétique ou figures de style.";};input.addEventListener("input",filter);clear.addEventListener("click",()=>{input.value="";filter();input.focus()});filter()}
setupSubjectSearch();

// Planning personnalisé : une séance quotidienne, ajustée aux matières choisies et aux progrès.
function dateKey(date){return date.getFullYear()+"-"+String(date.getMonth()+1).padStart(2,"0")+"-"+String(date.getDate()).padStart(2,"0")}
function displayDate(key){return new Date(key+"T12:00:00").toLocaleDateString("fr-FR",{weekday:"long",day:"numeric",month:"long"})}
function renderPlannerChoices(){const el=document.querySelector("#weakSubjectChoices");if(!el)return;el.innerHTML=SUBJECTS.map(s=>`<label><input type="checkbox" name="weakSubject" value="${s.id}"><span>${s.emoji} ${s.name}</span></label>`).join("")}
function getPlanTask(subject,index,minutes){const modes=["notes","quiz","cards"];const mode=modes[index%3];let title,detail;if(mode==="notes"){const pending=subject.topics.find((_,i)=>!state.topics[subject.id+"-"+i]);title=pending?"Relire : "+pending.title:"Relire une fiche de "+subject.name;detail="Lis la fiche, puis reformule les idées essentielles sans regarder."}else if(mode==="quiz"){title="QCM de "+subject.name;detail="Réponds aux questions et lis attentivement les explications."}else{title="Flashcards : "+subject.name;detail="Essaie de répondre avant de retourner chaque carte."}return {mode,title,detail,minutes}}
function generatePlanner(){const form=document.querySelector("#plannerForm");const exam=form.examDate.value;const minutes=Number(form.dailyMinutes.value)||20;const weak=[...form.querySelectorAll('input[name="weakSubject"]:checked')].map(x=>x.value);if(!exam){toast("Choisis d’abord la date du brevet.");return}const today=new Date();today.setHours(0,0,0,0);const end=new Date(exam+"T00:00:00");if(end<today){toast("La date du brevet doit être aujourd’hui ou dans le futur.");return}const settings={examDate:exam,dailyMinutes:minutes,weakSubjects:weak};state.planner=state.planner||{done:{}};state.planner.settings=settings;state.planner.done=state.planner.done||{};saveState();renderPlanner();toast("Ton planning est prêt !")}
function renderPlanner(){const form=document.querySelector("#plannerForm"),out=document.querySelector("#plannerOutput");if(!form||!out)return;renderPlannerChoices();const settings=state.planner&&state.planner.settings;if(!settings){out.innerHTML='<p class="muted">Renseigne la date de l’examen pour préparer ton planning.</p>';return}form.examDate.value=settings.examDate||"";form.dailyMinutes.value=String(settings.dailyMinutes||20);form.querySelectorAll('input[name="weakSubject"]').forEach(x=>x.checked=(settings.weakSubjects||[]).includes(x.value));const today=new Date();today.setHours(0,0,0,0);const exam=new Date(settings.examDate+"T00:00:00");const daysLeft=Math.max(0,Math.ceil((exam-today)/86400000));const days=Math.min(7,daysLeft+1);if(exam<today){out.innerHTML='<p class="planner-note">La date enregistrée est passée. Modifie-la pour générer un nouveau planning.</p>';return}const subjects=SUBJECTS.map(s=>({s,score:getSubjectProgress(s),weak:(settings.weakSubjects||[]).includes(s.id)}));const done=state.planner.done||{};let html=`<div class="planner-summary"><strong>${daysLeft===0?'C’est le jour du brevet !':daysLeft+' jour'+(daysLeft>1?'s':'')+' avant le brevet'}</strong><span>${Object.values(done).filter(Boolean).length} séance(s) cochée(s)</span></div><div class="planner-days">`;for(let i=0;i<days;i++){const date=new Date(today);date.setDate(today.getDate()+i);const key=dateKey(date);const sorted=subjects.slice().sort((a,b)=>((b.weak?100:0)+(100-b.score))-((a.weak?100:0)+(100-a.score)));const chosen=sorted[i%sorted.length].s;const task=getPlanTask(chosen,i,settings.dailyMinutes||20);const id=key+"-"+chosen.id;const checked=!!done[id];html+=`<label class="planner-day ${checked?'is-done':''}"><input type="checkbox" data-plan-done="${id}" ${checked?'checked':''}><span class="planner-day-copy"><small>${displayDate(key)}</small><b>${chosen.emoji} ${chosen.name} · ${task.title}</b><span>${task.detail}</span><em>${task.minutes} min</em></span><span class="planner-check">${checked?'✓':'○'}</span></label>`}html+='</div><p class="tiny muted">Le planning est indicatif : il répartit les révisions selon tes choix et la progression enregistrée sur cet appareil. Il ne remplace pas le programme officiel ni les consignes de tes professeurs.</p>';out.innerHTML=html;out.querySelectorAll('[data-plan-done]').forEach(c=>c.addEventListener('change',()=>{state.planner.done=state.planner.done||{};state.planner.done[c.dataset.planDone]=c.checked;saveState();renderPlanner()}))}
renderPlannerChoices();
document.querySelector("#plannerForm").addEventListener("submit",e=>{e.preventDefault();generatePlanner()});
document.querySelectorAll("[data-check]").forEach(c=>{c.checked=!!state.oral[c.dataset.check];c.addEventListener("change",()=>{state.oral[c.dataset.check]=c.checked;saveState()})});
document.querySelector("#resetBtn").addEventListener("click",()=>{if(confirm("Effacer toute ta progression sur cet appareil ? Cette action est irréversible.")){state=emptyState();saveState();renderPlanner();document.querySelectorAll("[data-check]").forEach(c=>c.checked=false);toast("Progression réinitialisée.")}});
window.addEventListener("beforeinstallprompt",e=>{e.preventDefault();installPrompt=e;document.querySelector("#installBtn").classList.remove("hidden")});
document.querySelector("#installBtn").addEventListener("click",async()=>{if(!installPrompt){toast("Dans le menu du navigateur, choisis « Installer l’application » ou « Ajouter à l’écran d’accueil ».");return}installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;document.querySelector("#installBtn").classList.add("hidden")});
if("serviceWorker" in navigator && location.protocol.startsWith("http"))window.addEventListener("load",()=>navigator.serviceWorker.register("./sw.js").catch(()=>{}));

// Export/import de sauvegarde : les données restent locales à l’appareil.
document.querySelector("#exportBtn").addEventListener("click",()=>{
  const blob=new Blob([JSON.stringify({format:"cap-brevet-backup-v1",exportedAt:new Date().toISOString(),progress:state},null,2)],{type:"application/json"});
  const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="cap-brevet-sauvegarde.json";document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);toast("Sauvegarde exportée.");
});
document.querySelector("#importBtn").addEventListener("click",()=>document.querySelector("#importFile").click());
document.querySelector("#importFile").addEventListener("change",async e=>{
  const file=e.target.files&&e.target.files[0];if(!file)return;
  try{const data=JSON.parse(await file.text());const p=data.progress||data;if(!p||typeof p!=="object"||!p.topics||!p.quizzes||!p.cards)throw new Error("invalid");
    if(!confirm("Importer cette sauvegarde et remplacer la progression actuelle ?")){e.target.value="";return}
    state={...emptyState(),...p,topics:p.topics||{},quizzes:p.quizzes||{},cards:p.cards||{},oral:p.oral||{},missed:p.missed||{},planner:{settings:null,done:{},...(p.planner||{})}};saveState();renderPlanner();document.querySelectorAll("[data-check]").forEach(c=>c.checked=!!state.oral[c.dataset.check]);toast("Sauvegarde importée.");e.target.value="";
  }catch(err){alert("Ce fichier ne semble pas être une sauvegarde Cap Brevet valide.");e.target.value=""}
});
